    public function filterByFechaDescripciones($fechaDescripciones = null, $comparison = null)
    {
        if (is_array($fechaDescripciones)) {
            $useMinMax = false;
            if (isset($fechaDescripciones['min'])) {
                $this->addUsingAlias(IsadPeer::FECHA_DESCRIPCIONES, $fechaDescripciones['min'], Criteria::GREATER_EQUAL);
                $useMinMax = true;
