            if (isset($fechaDescripciones['max'])) {
                $this->addUsingAlias(IsadPeer::FECHA_DESCRIPCIONES, $fechaDescripciones['max'], Criteria::LESS_EQUAL);
                $useMinMax = true;
            }
            if ($useMinMax) {
